SELECT *
FROM tms_accrual


        AND remark = #{req.remark}


        AND trade_number LIKE CONCAT('%', #{req.tradeNumber}, '%')


        AND accrual_date >= #{req.dateStart}


        AND accrual_date <= #{req.dateEnd}


        AND currency = #{req.currency}


        AND market_value >= #{req.marketValueMin}


        AND market_value <= #{req.marketValueMax}


        AND isin = #{req.isin}


        AND interest_journal_status = #{req.interestJournalStatus}


        AND valuation_journal_status = #{req.valuationJournalStatus}


        AND alloc_prem_disc_journal_status = #{req.allocPremDiscJournalStatus}


        AND (
            interest_journal_no LIKE CONCAT('%', #{req.journalSequence}, '%')
            OR valuation_journal_no LIKE CONCAT('%', #{req.journalSequence}, '%')
            OR alloc_prem_disc_journal_no LIKE CONCAT('%', #{req.journalSequence}, '%')
        )


ORDER BY accrual_date DESC, created_time DESC

SELECT *
FROM tms_accrual
WHERE remark = #{remark}
AND currency = #{currency}
AND isin = #{isin}
AND accrual_date = #{accrualDate}

SELECT COALESCE(SUM(market_value), 0)
FROM tms_risk_monitoring
WHERE remark = #{remark}
and isin = #{isin}
AND currency = #{currency}
AND reporting_date = #{date}

SELECT COALESCE(accrued_valuation_change, 0)
FROM tms_accrual
WHERE remark = #{remark}
AND currency = #{currency}
AND isin = #{isin}
AND accrual_date = #{accrualDate}::date - 1

SELECT COALESCE(accrued_interest, 0)
FROM tms_accrual
WHERE remark = #{remark}
AND currency = #{currency}
AND isin = #{isin}
AND accrual_date = #{accrualDate}::date - 1

SELECT COALESCE(alloc_prem_disc, 0)
FROM tms_accrual
WHERE remark = #{remark}
AND currency = #{currency}
AND isin = #{isin}
AND accrual_date = #{accrualDate}::date - 1
